CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name NVARCHAR(150) NOT NULL,description NVARCHAR(1000),kind VARCHAR(16) NOT NULL,price DECIMAL(18,0) NOT NULL CHECK(price>=0),active BIT NOT NULL);
CREATE TABLE product_services (product_id BIGINT NOT NULL REFERENCES products(id),service_id BIGINT NOT NULL REFERENCES products(id),PRIMARY KEY(product_id,service_id));
CREATE TABLE vouchers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,customer_name NVARCHAR(150) NOT NULL,phone VARCHAR(20) NOT NULL,percentage INT NOT NULL CHECK(percentage BETWEEN 1 AND 100),valid_from TIMESTAMP(6) WITH TIME ZONE NOT NULL,valid_until TIMESTAMP(6) WITH TIME ZONE NOT NULL,revoked BIT NOT NULL,reserved_order_id VARCHAR(36),reserved_until TIMESTAMP(6) WITH TIME ZONE,used_order_id VARCHAR(36),used_at TIMESTAMP(6) WITH TIME ZONE,note NVARCHAR(500));
CREATE TABLE bookings (id VARCHAR(36) PRIMARY KEY,access_token VARCHAR(36) NOT NULL UNIQUE,customer_name NVARCHAR(150) NOT NULL,phone VARCHAR(20) NOT NULL,email VARCHAR(254),visit_date DATE NOT NULL,channel VARCHAR(16) NOT NULL,status VARCHAR(16) NOT NULL,voucher_code VARCHAR(64) REFERENCES vouchers(code),discount_percent INT NOT NULL,subtotal DECIMAL(18,0) NOT NULL,discount DECIMAL(18,0) NOT NULL,total DECIMAL(18,0) NOT NULL,created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,paid_at TIMESTAMP(6) WITH TIME ZONE,payment_method VARCHAR(30),payment_reference VARCHAR(100),sold_by VARCHAR(100));
CREATE INDEX ix_bookings_expiry ON bookings(status,expires_at);
CREATE TABLE booking_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,booking_id VARCHAR(36) NOT NULL REFERENCES bookings(id),product_id BIGINT NOT NULL REFERENCES products(id),name NVARCHAR(150) NOT NULL,included_services NVARCHAR(1000) NOT NULL,kind VARCHAR(16) NOT NULL,unit_price DECIMAL(18,0) NOT NULL,quantity INT NOT NULL CHECK(quantity>0));
CREATE INDEX ix_booking_lines_booking ON booking_lines(booking_id);
CREATE TABLE tickets (id VARCHAR(36) PRIMARY KEY,booking_id VARCHAR(36) NOT NULL REFERENCES bookings(id),qr_token VARCHAR(36) NOT NULL UNIQUE,product_name NVARCHAR(150) NOT NULL,included_services NVARCHAR(1000) NOT NULL,visit_date DATE NOT NULL,checked_in_at TIMESTAMP(6) WITH TIME ZONE,checked_in_by VARCHAR(100));
CREATE INDEX ix_tickets_booking ON tickets(booking_id);
CREATE TABLE audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,happened_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,actor VARCHAR(100) NOT NULL,action VARCHAR(60) NOT NULL,target VARCHAR(100) NOT NULL);
